def test_protocol():
    T = TypeVar('T')

    class ComparableProtocol(Protocol[T]):
        def comparable(self) -> T: ...

    def foo(a: ComparableProtocol[int]) -> str:
        raise NotImplemented

    @dc.dataclass(frozen=True)
    class ComparableInt(int, ComparableProtocol[int]):
        def comparable(self) -> int:
            return self

    assert foo(ComparableInt(5)) == '5'

